// Offline play for Wheelie Wahala. Generated by tools/build.mjs from tools/sw.template.js.
//  - the game's files are saved on first visit, so it starts with no connection
//  - the page itself is fetched fresh when online (so updates arrive), from the cache when not
//  - built files have hashed names, so cached copies never go stale
//  - start.ng sign-in, scores and the leaderboard always go to the network
const VERSION = '__VERSION__';
const CACHE = `wheelie-wahala-${VERSION}`;
const FILES = __FILES__;

self.addEventListener('install', (event) => {
  event.waitUntil(caches.open(CACHE).then((c) => c.addAll(FILES)).then(() => self.skipWaiting()));
});

self.addEventListener('activate', (event) => {
  event.waitUntil(
    caches.keys()
      .then((keys) => Promise.all(keys.filter((k) => k.startsWith('wheelie-wahala-') && k !== CACHE).map((k) => caches.delete(k))))
      .then(() => self.clients.claim()),
  );
});

self.addEventListener('fetch', (event) => {
  const req = event.request;
  if (req.method !== 'GET') return;
  const url = new URL(req.url);

  // start.ng itself (sign-in, connect page, API): never cached.
  if (url.hostname === 'start.ng' || url.hostname.startsWith('api.')) return;

  // Pages: network first, so a new version shows up straight away.
  if (req.mode === 'navigate') {
    event.respondWith(
      fetch(req)
        .then((res) => {
          const copy = res.clone();
          caches.open(CACHE).then((c) => c.put('index.html', copy));
          return res;
        })
        .catch(() => caches.match('index.html')),
    );
    return;
  }

  // Our files and fonts: cache first, then the network (and keep a copy).
  if (url.origin === location.origin || url.hostname.endsWith('fonts.googleapis.com') || url.hostname.endsWith('fonts.gstatic.com')) {
    event.respondWith(
      caches.match(req).then((hit) => hit || fetch(req).then((res) => {
        if (res.ok || res.type === 'opaque') {
          const copy = res.clone();
          caches.open(CACHE).then((c) => c.put(req, copy));
        }
        return res;
      })),
    );
  }
});
